const listMaintenancePlans = `-- name: ListMaintenancePlans :many
SELECT p.id, p.tank_id, p.equipment_id, e.name AS equipment_name, p.title, p.interval_days, p.timezone, p.starts_on,
       p.last_performed_at, p.next_due_on, p.active, p.notes, p.created_at, p.updated_at, p.version
FROM maintenance_plans p
LEFT JOIN tank_equipment e ON e.id = p.equipment_id
WHERE p.tank_id = $1
ORDER BY p.active DESC, p.next_due_on, p.id
`

type ListMaintenancePlansRow struct {
	ID              uuid.UUID
	TankID          uuid.UUID
	EquipmentID     *uuid.UUID
	EquipmentName   *string
	Title           string
	IntervalDays    int32
	Timezone        string
	StartsOn        time.Time
	LastPerformedAt *time.Time
	NextDueOn       time.Time
	Active          bool
	Notes           *string
	CreatedAt       time.Time
	UpdatedAt       time.Time
	Version         int32
}

// Active plans first, soonest due first.
func (q *Queries) ListMaintenancePlans(ctx context.Context, tankID uuid.UUID) ([]ListMaintenancePlansRow, error) {
	rows, err := q.db.Query(ctx, listMaintenancePlans, tankID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListMaintenancePlansRow{}
	for rows.Next() {
		var i ListMaintenancePlansRow
		if err := rows.Scan(
			&i.ID,
			&i.TankID,
			&i.EquipmentID,
			&i.EquipmentName,
			&i.Title,
			&i.IntervalDays,
			&i.Timezone,
			&i.StartsOn,
			&i.LastPerformedAt,
			&i.NextDueOn,
			&i.Active,
			&i.Notes,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockEquipment = `-- name: LockEquipment :one
SELECT id, tank_id, installed_at, removed_at, version FROM tank_equipment WHERE id = $1 FOR NO KEY UPDATE
`

type LockEquipmentRow struct {
	ID          uuid.UUID
	TankID      uuid.UUID
	InstalledAt time.Time
	RemovedAt   *time.Time
	Version     int32
}

// NO KEY UPDATE (id and tank_id never change) so FK checks from new events don't block on it.
func (q *Queries) LockEquipment(ctx context.Context, id uuid.UUID) (LockEquipmentRow, error) {
	row := q.db.QueryRow(ctx, lockEquipment, id)
	var i LockEquipmentRow
	err := row.Scan(
		&i.ID,
		&i.TankID,
		&i.InstalledAt,
		&i.RemovedAt,
		&i.Version,
	)
	return i, err
}

