const lockOwnerTanksForErasure = `-- name: LockOwnerTanksForErasure :exec
SELECT id FROM tanks WHERE owner_id = $1 ORDER BY id FOR UPDATE
`

// Account erasure: lock the owner's tanks first (a plain statement — a SELECT in an
// unreferenced CTE would never run), so shared writers, which take the tank lock first,
// can't add rows meanwhile. Then delete in FK order: events, plans, configurations,
// equipment; all before tanks.EraseUserData.
func (q *Queries) LockOwnerTanksForErasure(ctx context.Context, ownerID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockOwnerTanksForErasure, ownerID)
	return err
}

const nextConfigurationVersion = `-- name: NextConfigurationVersion :one
SELECT (COALESCE(max(version_no), 0) + 1)::integer AS version_no,
       COALESCE(max(effective_at), 'epoch')::timestamptz AS latest_effective_at
FROM equipment_configurations WHERE equipment_id = $1
`

type NextConfigurationVersionRow struct {
	VersionNo         int32
	LatestEffectiveAt time.Time
}

// Run with the equipment row locked (LockEquipment) so concurrent writers serialize. The
// latest effective_at (epoch when there is none) keeps version order = timeline order.
func (q *Queries) NextConfigurationVersion(ctx context.Context, equipmentID uuid.UUID) (NextConfigurationVersionRow, error) {
	row := q.db.QueryRow(ctx, nextConfigurationVersion, equipmentID)
	var i NextConfigurationVersionRow
	err := row.Scan(&i.VersionNo, &i.LatestEffectiveAt)
	return i, err
}

const removeEquipment = `-- name: RemoveEquipment :execrows
UPDATE tank_equipment
SET removed_at = $1::timestamptz, removal_reason = $2, updated_at = $3,
    version = version + 1
WHERE id = $4 AND removed_at IS NULL
`

type RemoveEquipmentParams struct {
	RemovedAt     time.Time
	RemovalReason *string
	Now           time.Time
	ID            uuid.UUID
}

func (q *Queries) RemoveEquipment(ctx context.Context, arg RemoveEquipmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeEquipment,
		arg.RemovedAt,
		arg.RemovalReason,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const shareLockEquipment = `-- name: ShareLockEquipment :one
SELECT id, tank_id, installed_at, removed_at FROM tank_equipment WHERE id = $1 FOR SHARE
`

type ShareLockEquipmentRow struct {
	ID          uuid.UUID
	TankID      uuid.UUID
	InstalledAt time.Time
	RemovedAt   *time.Time
}

// Taken when a plan or event is linked to the device, so a concurrent removal (NO KEY
// UPDATE) either sees the link and deactivates the plan, or is seen as removed here.
// Lock order everywhere: tank, equipment, plan.
func (q *Queries) ShareLockEquipment(ctx context.Context, id uuid.UUID) (ShareLockEquipmentRow, error) {
	row := q.db.QueryRow(ctx, shareLockEquipment, id)
	var i ShareLockEquipmentRow
	err := row.Scan(
		&i.ID,
		&i.TankID,
		&i.InstalledAt,
		&i.RemovedAt,
	)
	return i, err
}

const updateEquipment = `-- name: UpdateEquipment :execrows
UPDATE tank_equipment
SET category = $1, name = $2, manufacturer = $3, model = $4,
    serial_number = $5, purchased_on = $6,
    warranty_until = $7, notes = $8,
    updated_at = $9, version = version + 1
WHERE id = $10 AND version = $11 AND removed_at IS NULL
`

type UpdateEquipmentParams struct {
	Category      string
	Name          string
	Manufacturer  *string
	Model         *string
	SerialNumber  *string
	PurchasedOn   *time.Time
	WarrantyUntil *time.Time
	Notes         *string
	Now           time.Time
	ID            uuid.UUID
	Version       int32
}

func (q *Queries) UpdateEquipment(ctx context.Context, arg UpdateEquipmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateEquipment,
		arg.Category,
		arg.Name,
		arg.Manufacturer,
		arg.Model,
		arg.SerialNumber,
		arg.PurchasedOn,
		arg.WarrantyUntil,
		arg.Notes,
		arg.Now,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

